1	import path from "node:path";
2	import fs from "node:fs";
3	import pino from "pino";
4	import { pinoHttp } from "pino-http";
5	import { readConfigFile } from "../config-file.js";
6	import { resolveDefaultLogsDir, resolveHomeAwarePath } from "../home-paths.js";
7	import { shouldSilenceHttpSuccessLog } from "./http-log-policy.js";
8	
9	function resolveServerLogDir(): string {
10	  const envOverride = process.env.PAPERCLIP_LOG_DIR?.trim();
11	  if (envOverride) return resolveHomeAwarePath(envOverride);
12	
13	  const fileLogDir = readConfigFile()?.logging.logDir?.trim();
14	  if (fileLogDir) return resolveHomeAwarePath(fileLogDir);
15	
16	  return resolveDefaultLogsDir();
17	}
18	
19	const logDir = resolveServerLogDir();
20	fs.mkdirSync(logDir, { recursive: true });
21	
22	const logFile = path.join(logDir, "server.log");
23	
24	const sharedOpts = {
25	  translateTime: "SYS:HH:MM:ss",
26	  ignore: "pid,hostname",
27	  singleLine: true,
28	};
29	
30	export const logger = pino({
31	  level: "debug",
32	  redact: ["req.headers.authorization"],
33	}, pino.transport({
34	  targets: [
35	    {
36	      target: "pino-pretty",
37	      options: { ...sharedOpts, ignore: "pid,hostname,req,res,responseTime", colorize: true, destination: 1 },
38	      level: "info",
39	    },
40	    {
41	      target: "pino-pretty",
42	      options: { ...sharedOpts, colorize: false, destination: logFile, mkdir: true },
43	      level: "debug",
44	    },
45	  ],
46	}));
47	
48	export const httpLogger = pinoHttp({
49	  logger,
50	  customLogLevel(_req, res, err) {
51	    if (shouldSilenceHttpSuccessLog(_req.method, _req.url, res.statusCode)) {
52	      return "silent";
53	    }
54	    if (err || res.statusCode >= 500) return "error";
55	    if (res.statusCode >= 400) return "warn";
56	    return "info";
57	  },
58	  customSuccessMessage(req, res) {
59	    return `${req.method} ${req.url} ${res.statusCode}`;
60	  },
61	  customErrorMessage(req, res, err) {
62	    const ctx = (res as any).__errorContext;
63	    const errMsg = ctx?.error?.message || err?.message || (res as any).err?.message || "unknown error";
64	    return `${req.method} ${req.url} ${res.statusCode} — ${errMsg}`;
65	  },
66	  customProps(req, res) {
67	    if (res.statusCode >= 400) {
68	      const ctx = (res as any).__errorContext;
69	      if (ctx) {
70	        return {
71	          errorContext: ctx.error,
72	          reqBody: ctx.reqBody,
73	          reqParams: ctx.reqParams,
74	          reqQuery: ctx.reqQuery,
75	        };
76	      }
77	      const props: Record<string, unknown> = {};
78	      const { body, params, query } = req as any;
79	      if (body && typeof body === "object" && Object.keys(body).length > 0) {
80	        props.reqBody = body;
81	      }
82	      if (params && typeof params === "object" && Object.keys(params).length > 0) {
83	        props.reqParams = params;
84	      }
85	      if (query && typeof query === "object" && Object.keys(query).length > 0) {
86	        props.reqQuery = query;
87	      }
88	      if ((req as any).route?.path) {
89	        props.routePath = (req as any).route.path;
90	      }
91	      return props;
92	    }
93	    return {};
94	  },
95	});
